/** Category select prefix — picking an option updates the leading trigger label. */
export const WithLeadingDropdown = {
    render: () => ({
        props: {
            category: 'All',
            categories: ['All', 'Articles', 'Pages'],
            select(value) {
                this.category = value;
            },
        },
        template: `
			<div class="w-full max-w-sm">
				<div hlmInputGroup>
					<div hlmInputGroupAddon>
						<button hlmInputGroupButton variant="ghost" [hlmDropdownMenuTrigger]="menu" aria-label="Open dropdown menu for {{ category }}">{{ category }}</button>
						<ng-template #menu>
							<hlm-dropdown-menu>
								@for (option of categories; track option) {
									<button hlmDropdownMenuItem (click)="select(option)" aria-label="Select {{ option }}">{{ option }}</button>
								}
							</hlm-dropdown-menu>
						</ng-template>
					</div>
					<input hlmInputGroupInput [placeholder]="'Search ' + category.toLowerCase() + '…'" />
				</div>
			</div>
		`,
    }),
};
